  paySlipsAvailableDate: "2026-12-01",
  payslips: [{
    employee: { id: EMP_ID },
    specifications: [
      {
        employee: { id: EMP_ID },
        salaryType: { id: FASTLONN_ID },
        description: "Fastlønn",
        year: 2026,
        month: 12,
        count: 1,
